from functools import reduce


def merge(base, override):
    """Layer `override` on top of `base`."""
    def _recursive_merge(b, o):
        if isinstance(b, dict) and isinstance(o, dict):
            res = copy.deepcopy(b)
            for k, v in o.items():
                if v is None:
                    if k in res:
                        del res[k]
                elif k in res:
                    res[k] = _recursive_merge(res[k], v)
                else:
                    res[k] = copy.deepcopy(v)
            return res
        else:
            return copy.deepcopy(o)

    if not isinstance(base, dict) or not isinstance(override, dict):
        return copy.deepcopy(override)

    return _recursive_merge(base, override)


def load_layers(*layers):
    """Merge config layers left to right (later layers win)."""
    return reduce(merge, layers, {})
